package app.shobdo.keyboard.banglish

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Accuracy of the Banglish engine against the shipped lexicon.
 *
 * The corpus (`app/src/test/resources/banglish_cases.tsv`) is generated by
 * `tools/build_banglish_lexicon.py` from the same word list the app ships, with a quarter of
 * the rows written in a casual spelling (`aami`, `bhaloo`, `shomoy`). The numbers printed here
 * are the ones quoted in the README and in the release notes.
 */
class BanglishAccuracyTest {

    private val assets = File(System.getProperty("shobdo.assets") ?: "src/main/assets")

    private val skeleton = SkeletonRules.fromJson(
        File(assets, SkeletonRules.ASSET_PATH).readText(Charsets.UTF_8)
    )

    private val phonetic = BanglishEngine.fromJson(
        File(assets, BanglishEngine.RULE_ASSET_PATH).readText(Charsets.UTF_8)
    )

    private val lexicon = BanglishLexicon.parse(
        File(assets, BanglishLexicon.ASSET_PATH).readLines(Charsets.UTF_8)
    )

    private val engine = CandidateEngine(phonetic, skeleton, lexicon, learned = null)

    private fun cases(): List<Pair<String, String>> =
        File("src/test/resources/banglish_cases.tsv").readLines(Charsets.UTF_8)
            .filter { it.isNotBlank() && !it.startsWith("#") }
            .mapNotNull { line ->
                val parts = line.split('\t')
                if (parts.size >= 2) parts[0] to parts[1] else null
            }

    @Test
    fun `the lexicon is the size the build script produced`() {
        assertTrue("lexicon words: ${lexicon.wordCount}", lexicon.wordCount > 40_000)
    }

    @Test
    fun `skeleton matches the build time implementation`() {
        // Values produced by tools/build_banglish_lexicon.py for the same table.
        assertEquals("ami", skeleton.ofBangla("আমি"))
        assertEquals("tumi", skeleton.ofBangla("তুমি"))
        assertEquals("bhalo", skeleton.ofBangla("ভালো"))
        assertEquals("bangla", skeleton.ofBangla("বাংলা"))
        // A medial inherent vowel is not written: কেমন is k-e-m-n.
        assertEquals("kemn", skeleton.ofBangla("কেমন"))
        // Casual spellings reduce to the same key as the plain one.
        assertEquals("ami", skeleton.ofRoman("aami"))
        assertEquals("u", skeleton.ofRoman("oo"))
        assertEquals("s", skeleton.ofRoman("sh"))
        assertEquals("j", skeleton.ofRoman("z"))
        assertEquals("ph", skeleton.ofRoman("f"))
        assertEquals("kh", skeleton.ofRoman("kh"))
        assertEquals("k", skeleton.ofRoman("k"))
    }

    @Test
    fun `the four anchors are the first candidate`() {
        val anchors = mapOf(
            "ami" to "আমি",
            "tumi" to "তুমি",
            "bhalo" to "ভালো",
            "bangla" to "বাংলা"
        )
        for ((roman, expected) in anchors) {
            val top = engine.candidates(roman)
            assertEquals("$roman -> ${top.firstOrNull()?.text}", expected, top.firstOrNull()?.text)
        }
    }

    @Test
    fun `the roman text stays within the first three candidates`() {
        for (roman in listOf("ami", "k", "bhalo", "zzzz", "bangla", "school")) {
            val texts = engine.candidates(roman).map { it.text }
            val index = texts.indexOf(roman)
            assertTrue("$roman missing from $texts", index >= 0)
            assertTrue("$roman was at $index in $texts", index <= 2)
        }
    }

    @Test
    fun `top one and top five accuracy clear the release bar`() {
        val all = cases()
        assertTrue("corpus has ${all.size} cases", all.size >= 300)

        var topOne = 0
        var topFive = 0
        val misses = ArrayList<String>()
        for ((roman, expected) in all) {
            val texts = engine.candidates(roman).map { it.text }
            if (texts.firstOrNull() == expected) topOne++
            if (texts.take(5).contains(expected)) topFive++ else misses.add(roman)
        }
        val oneRate = topOne * 100.0 / all.size
        val fiveRate = topFive * 100.0 / all.size
        println("BANGLISH ACCURACY: top-1 %.1f%% (%d/%d), top-5 %.1f%% (%d/%d)"
            .format(oneRate, topOne, all.size, fiveRate, topFive, all.size))
        if (misses.isNotEmpty()) {
            println("MISSES (${misses.size}):")
            println("  romans: " + misses.take(20).joinToString(", "))
        }

        assertTrue("top-1 was %.1f%%".format(oneRate), oneRate >= 80.0)
        assertTrue("top-5 was %.1f%%".format(fiveRate), fiveRate >= 95.0)
    }

    @Test
    fun `candidate lookup is fast enough for a keystroke`() {
        val samples = listOf("ami", "bhalo", "bangla", "kemon", "dhonnobad", "shomoy", "bhalobasha")
        // Warm up so the measurement is not dominated by class loading.
        repeat(50) { samples.forEach { engine.candidates(it) } }
        val start = System.nanoTime()
        val runs = 200
        repeat(runs) { samples.forEach { engine.candidates(it) } }
        val perCall = (System.nanoTime() - start) / (runs * samples.size.toDouble()) / 1_000_000.0
        println("BANGLISH LOOKUP: %.2f ms per keystroke".format(perCall))
        assertTrue("lookup took %.2f ms".format(perCall), perCall < 10.0)
    }
}
